    },
  });

  // --- Player pointer: pulsing ring + heading arrow ------------------------------
  map.addImage("player-pulse", pulsingRing(map), { pixelRatio: 2 });
  map.addImage("player-arrow", arrowImage(), { pixelRatio: 2 });
  map.addSource("player", { type: "geojson", data: EMPTY });
  map.addLayer({
    id: "player-pulse",
    type: "symbol",
    source: "player",
    slot: "top",
    layout: {
