1	"use client";
2	
3	import { useEffect, useRef, useState, useSyncExternalStore } from "react";
4	import MapView, { type MapHandle } from "./map/MapView";
5	import LoadingScreen from "./map/LoadingScreen";
6	import Hud from "./Hud";
7	import TabBar, { type Tab } from "./TabBar";
8	import Sheet from "./Sheet";
9	import LocationPrompt from "./LocationPrompt";
10	import ProfilePanel from "./ProfilePanel";
11	import DemoPanel from "./DemoPanel";
12	import LocateButton from "./LocateButton";
13	
14	const TITLES: Record<Exclude<Tab, "map">, string> = { missions: "Missions", crew: "Crew", profile: "Profile" };
15	
16	// `?denied=uwo` is set by the Auth0 callback when a non-Western account signs in. Read once.
17	let deniedAtLoad: boolean | undefined;
18	const readDenied = () =>
19	  (deniedAtLoad ??= new URLSearchParams(window.location.search).get("denied") === "uwo");
20	const noopSubscribe = () => () => {};
21	
22	export default function GameScreen() {
23	  const map = useRef<MapHandle | null>(null);
24	  const [mapState, setMapState] = useState<"loading" | "ready" | "unavailable">("loading");
25	  const [reason, setReason] = useState<string>();
26	  const denied = useSyncExternalStore(noopSubscribe, readDenied, () => false);
27	  const [chosenTab, setTab] = useState<Tab | null>(null);
28	  const tab: Tab = chosenTab ?? (denied ? "profile" : "map");
29	
30	  useEffect(() => {
31	    if (denied) window.history.replaceState(null, "", "/");
32	  }, [denied]);
33	
34	  return (
35	    <main className="absolute inset-0">
36	      <MapView
37	        ref={map}
38	        onReady={() => setMapState("ready")}
39	        onUnavailable={(r) => {
40	          setReason(r);
41	          setMapState("unavailable");
42	        }}
43	      />
44	      <Hud />
45	      {mapState === "ready" && (
46	        <>
47	          <LocationPrompt />
48	          <LocateButton map={map} />
49	        </>
50	      )}
51	
52	      <Sheet open={tab !== "map"} title={tab === "map" ? "" : TITLES[tab]} onClose={() => setTab("map")}>
53	        {tab === "profile" ? (
54	          <ProfilePanel denied={denied} />
55	        ) : (
56	          <p className="pb-4 text-[15px] text-ink/70">
57	            {tab === "missions"
58	              ? "The Goose is lining up jobs across Forest State. Missions drop tomorrow."
59	              : "Crews and friends are coming soon."}
60	          </p>
61	        )}
62	      </Sheet>
63	
64	      <TabBar active={tab} onChange={setTab} />
