77	  wired = true;
78	  subscribeFog(() => listeners.forEach((l) => l()));
79	}
80	
81	export function getDistrictStats(): DistrictStat[] {
82	  wire();
83	  // Keyed on the fog's cell count (cells are only ever added), so callers never see stale stats
84	  // regardless of listener order.
85	  const count = getFogSnapshot().count;
86	  if (count !== computedFor) {
87	    recompute();
88	    computedFor = count;
89	  }
90	  return stats;
91	}
92	
93	export function subscribeDistricts(l: () => void) {
94	  wire();
95	  listeners.add(l);
96	  return () => listeners.delete(l);
97	}

