      0 0 0 12px rgb(255 255 255 / 0.08),
      0 40px 120px -20px rgb(255 79 139 / 0.45);
  }
}

/* ---------- Map ---------- */
.mapboxgl-map {
  font-family: inherit;
}

.mapboxgl-ctrl-bottom-left,
.mapboxgl-ctrl-bottom-right {
