125	  const rings = (g.type === "Polygon" ? [g.coordinates[0]] : g.type === "MultiPolygon" ? g.coordinates.map((p) => p[0]) : []) as LngLat[][];
126	  return rings.some((ring) =>
127	    MODEL_RINGS.some((m) => {
128	      let hits = 0;
129	      for (const v of ring) if (pointInRing(v, m)) hits++;
130	      if (hits >= Math.max(1, Math.ceil(ring.length * 0.5))) return true; // mostly inside a model
131	      return m.some((v) => pointInRing(v, ring));
132	    }),
133	  );
134	}
135	/** Night/dusk = glowing windows; dawn/day = reflective glass (separate `-day` glb, loaded on demand). */
136	const isNightLook = (preset: string) => preset === "night" || preset === "dusk";
137	const modelIdExpr = (preset: string) => (isNightLook(preset) ? ["get", "model"] : ["concat", ["get", "model"], "-day"]) as never;
138	function applyModelVariant(map: MapboxMap, preset: string) {
139	  const suffix = isNightLook(preset) ? "" : "-day";
140	  for (const m of MODELS) {
141	    const id = m.id + suffix;
142	    if (!map.hasModel(id)) map.addModel(id, new URL(m.url.replace(/\.glb$/, `${suffix}.glb`), window.location.origin).href);
143	  }
144	  if (map.getLayer("campus-models")) map.setLayoutProperty("campus-models", "model-id", modelIdExpr(preset));
145	}
146	/** Windows glow at night, barely by day. */
147	const modelGlow = (preset: string) => (preset === "night" ? 1 : preset === "dusk" || preset === "dawn" ? 0.7 : 0.12);
148	
149	/** Ease so a tapped building sits in the visible map above the bottom sheet. */
150	function frameBuilding(map: MapboxMap, ring: LngLat[]) {
151	  let [w, s2, e2, n] = [180, 90, -180, -90];
152	  for (const [x, y] of ring) [w, s2, e2, n] = [Math.min(w, x), Math.min(s2, y), Math.max(e2, x), Math.max(n, y)];
153	  const h = map.getContainer().clientHeight;
154	  map.fitBounds(
155	    [
156	      [w, s2],
157	      [e2, n],
158	    ],
