  const h = map.getContainer().clientHeight;
  let best: (typeof MODEL_PARTS)[number] | null = null;
  for (let dy = 0; point.y + dy < h; dy += 6) {
    const g = map.unproject([point.x, point.y + dy]);
    const here: LngLat = [g.lng, g.lat];
    const part = MODEL_PARTS.find((p) => pointInRing(here, p.ring));
    if (!part) continue;
    const d = distanceM(tap, here);
    if (part.height + 1 >= d / Math.tan(pitch)) best = part; // keep going: a nearer blocker wins
  }
  return best;
}

